import { Trans, useLingui } from "@lingui/react/macro";
import { useQuery } from "@tanstack/react-query";
import { useState } from "react";

import { Input } from "@anlg/ui/components/ui/input";

import { SettingsPageTitle } from "~/settings/page-title";

export type LicenseEntry = { name: string; version: string; license: string };
export type LicenseData = {
  app_license: string;
  cargo: LicenseEntry[];
  npm: LicenseEntry[];
};

// ASPC D5.1: the app's MIT licence, unchanged, and the third-party licences.
// The list is generated by `node scripts/generate-licenses.mjs` from Cargo
// and pnpm metadata and loaded only when this page opens.
async function loadLicenses(): Promise<LicenseData> {
  const data = await import("./third-party-licenses.gen.json");
  return data.default as LicenseData;
}

export function filterLicenses(
  entries: LicenseEntry[],
  query: string,
): LicenseEntry[] {
  const needle = query.trim().toLowerCase();
  if (!needle) return entries;
  return entries.filter(
    (entry) =>
      entry.name.toLowerCase().includes(needle) ||
      entry.license.toLowerCase().includes(needle),
  );
}

export function SettingsAbout() {
  const { t } = useLingui();
  const [query, setQuery] = useState("");
  const licenses = useQuery({
    queryKey: ["about", "licenses"],
    queryFn: loadLicenses,
    staleTime: Infinity,
  });

  return (
    <div className="flex flex-col gap-8">
      <SettingsPageTitle title={t`About`} />

      <section className="flex flex-col gap-2">
        <h3 className="text-sm font-semibold">
          <Trans>Licence</Trans>
        </h3>
        <pre className="bg-muted text-muted-foreground max-h-64 overflow-auto rounded-md p-3 text-xs whitespace-pre-wrap select-text">
          {licenses.data?.app_license ?? ""}
        </pre>
      </section>

      <section className="flex flex-col gap-3">
        <h3 className="text-sm font-semibold">
          <Trans>Third-party licences</Trans>
        </h3>
        <p className="text-muted-foreground text-xs">
          <Trans>
            Open-source packages this app is built with, and their licences.
          </Trans>
        </p>
        <Input
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          placeholder={t`Filter by package or licence`}
          aria-label={t`Filter by package or licence`}
        />
        {licenses.data ? (
          <>
            <LicenseList
              title={t`Rust crates`}
              entries={filterLicenses(licenses.data.cargo, query)}
            />
            <LicenseList
              title={t`JavaScript packages`}
              entries={filterLicenses(licenses.data.npm, query)}
            />
          </>
        ) : null}
      </section>
    </div>
  );
}

function LicenseList({
  title,
  entries,
}: {
  title: string;
  entries: LicenseEntry[];
}) {
  return (
    <details className="flex flex-col gap-1">
      <summary className="cursor-pointer text-sm font-medium">
        {title} ({entries.length})
      </summary>
      <ul className="mt-2 flex flex-col gap-0.5">
        {entries.map((entry) => (
          <li
            key={`${entry.name}@${entry.version}`}
            className="flex justify-between gap-4 font-mono text-xs"
          >
            <span className="truncate select-text">
              {entry.name} {entry.version}
            </span>
            <span className="text-muted-foreground shrink-0">
              {entry.license || "—"}
            </span>
          </li>
        ))}
      </ul>
    </details>
  );
}
